import { Grid, List } from "@arco-design/web-react";
import React from "react";
import styles from './style.module.less';
import { ModuleItem } from "@/components/CustomPage/interface";
import CustomItem from "./CustomItem";


interface CustomList {
    list: ModuleItem[]
}

const CustomList = ({ list }: CustomList) => {


    return (
        <Grid.Row gutter={[16, 16]}>
            {list.map((item) => {

                return (
                    <Grid.Col span={12} key={item.key}>
                        <CustomItem item={item} key={item.key} />
                    </Grid.Col>
                )
            })}
        </Grid.Row>
    )
}

export default CustomList;