import app from "@/store/app";
import ajax from "@/utils/ajax";
import { getModuleItem } from "@/utils/module";
import { action, observable, toJS, makeObservable } from "mobx";
import { ModuleItem } from "@/components/CustomPage/interface";
import React from "react";
import { AppPlugin } from "@/types/app";
import { getUuid } from "@/utils";

interface PublicModules extends AppPlugin {
    PublicModule: ModuleItem[];
}

interface GroupListItem {
    id: string;
    key: string;
    name: string;
    list: ModuleItem[];
}

class Store {

    constructor(){
        makeObservable(this);
        Promise.all([
            this.getModules(),
            this.getPublicModule()
        ]).then(() => {
            // 模块合并
            this.combinationModules();
        })
    }

    @observable activeTab: string = "custom";
    @action setActiveTab = (key: string) => {
        this.activeTab = key;
    }

    @observable list: GroupListItem[] = [];
    @action setList(data){
        this.list = data;
    } 


    @observable modules: ModuleItem[] = [];
    @action setModules = (data) => {
        this.modules = data;
    }

    @observable publicModules: PublicModules[] = [];
    @action setPublicModules = (data) => {
        this.publicModules = data;
    }

    // 获取项目模块列表
    getModules = () => {
        return ajax.post('/apijson/get', {
            'Module[]': {
                count: 0,
                Module: {
                  platform: app.platform,
                  deletedTime: 0,
                  "@column": "id,moduleId,pluginId,name,imgUrl,nickname,description,deletedTime,category,display,extraInfo,platform,price,manufacturer,props,source",
                  "@order": "sort+"
                }
            }
        }).then((res) => {
            const list = res.Module.map((o) => getModuleItem(o));
            this.setModules(list);
        })
    }

    // 获取公共组件模块列表
    getPublicModule(){
        const plugins = app.plugins;
        if(!plugins.length) return Promise.resolve(true);
        return ajax.post('/apijson/get', {
            "Plugins[]": {
                "count": 0,
                "Plugins": {
                    "id{}": app.plugins.map((o) => o.id),
                },
                "PublicModule[]": {
                    count: 2,
                    "PublicModule": {
                        status: 1,
                        'pluginId@': "Plugins[]/Plugins/id",
                        platform: app.platform,
                        "@order": "pluginId",
                        "@column": "id,moduleId,pluginId,name,imgUrl,nickname,description,category,display,extraInfo,platform,price,manufacturer,props,source",
                    }
                }
            }
        }).then((res) => {
            this.setPublicModules(res.Plugins.map((o) => ({
                ...o,
                PublicModule: o.PublicModule.map((o) => getModuleItem(o))
            })));
        })
    }


    /**
     * 组合modules集合
     */
    combinationModules(){
        const modules = toJS(this.modules);
        const plugins = toJS(this.publicModules);
        const objs: Record<string, GroupListItem> = {};
        const outhers: ModuleItem[] = []; // 没有分组的组件
        const map = new Map(modules.map((o) => [o.key, true]));
        console.log('modules', modules)
        for (const item of plugins) {
            objs[item.id] = {
                id: item.id,
                key: item.id,
                name: item.name,
                // 筛除重复的组建
                list: item.PublicModule.filter((o) => !map.has(o.key)),
            }
        }
        console.log('plugins', plugins)
        let len = modules.length - 1;
        for(let i = len; i >= 0; i--){
            let item = modules[i];
            if(item.pluginId && objs[item.pluginId]){
                objs[item.pluginId].list.unshift(item);
            }else {
                outhers.push(item);
            }
        }
        const list: GroupListItem[] = Object.values(objs);
        if(outhers.length){
            let uid = getUuid()
            list.push({ id: uid, key: uid , name: "其他", list: outhers });
        }
        this.setList(list);
        console.log('setList', list, plugins, objs)
    }

}

export default Store;