import React, { useMemo } from "react";
import Store from './store';
import { useObserver } from "mobx-react-lite";
import { DragView, DropView } from "react-converter-code";
import { Collapse, Empty, Grid, List, Tabs, Typography } from "@arco-design/web-react";
import styles from './style.module.less';
import modules from "@/store/module";
import { htmlElements, htmlModuleList } from "@/utils/database";
import CustomList from "./CustomList";
import CustomItem from "./CustomItem";
import IconList from "@/components/CustomPage/Menu/Icon";
import { PageRouteModule } from "@/environments/module";
import classNames from "classnames";


const { Row, Col } = Grid;

const ModuleList = () => {

    const store = useMemo(() => new Store(), []);


    return useObserver(() => {

        const { activeTab, setActiveTab } = store


        const systems = useMemo(() => {

            return (
                <div className={styles.component}>
                    <div className={styles.group}>
                        系统
                        <Grid.Row>
                            <Grid.Col span={12}>
                                <CustomItem item={PageRouteModule} />
                            </Grid.Col>
                        </Grid.Row>
                    </div>
                    <div className={styles.group}>
                        html标签
                    </div>
                    <List
                        className={styles.htmlList}
                        grid={{ gutter: [16,24], column: 2 }}
                        dataSource={htmlModuleList}
                        render={(item) => {
                            return (
                                <List.Item className={styles.htmlItem} style={{ padding: 0 }}>
                                    <DragView data={item}
                                    >
                                        <div className={classNames('shadow-md', styles.htmlItemName)}>
                                            {item.nickname || item.name}
                                        </div>
                                    </DragView>
                                </List.Item>
                            );
                        }}
                    />
                </div>
            )
        },[])
 
        const customs = useMemo(() => {

            const modules = store.list;
            return (
                <div className={styles.component}>
                    <Collapse 
                        key={modules.length}
                        bordered={false}
                        defaultActiveKey={modules.map((o) => o.key)}
                        className={styles.collapse}
                    >
                        {modules.map((o) => {
                            return (
                                <Collapse.Item key={o.key} name={o.key} header={o.name}>
                                    <CustomList list={o.list}></CustomList>
                                </Collapse.Item>
                            )
                        })}
                    </Collapse>
                </div>
            )

            return (
                <div className={styles.component}>
    
                    {store.list.map((option) => {
    
    
                        if(!option.list.length){
                            return (
                                <div key={option.id} className={styles.item}>
                                    <div className={styles.group}>
                                        {option.name}
                                    </div>
                                    <Empty />
                                </div>
                            )
                        }
    
                        return (
                            <div key={option.id} className={styles.item}>
                                <div className={styles.group}>
                                    {option.name}
                                </div>
                                <Row gutter={[16,16]}>
                                    {option.list.map((item) => {  
                                        return (
                                            <Col key={item.key} span={12}>
                                                <DragView data={item}>
                                                    <div className={styles.imgView}>
                                                        <img
                                                            className={styles.image}
                                                            alt="dessert"
                                                            src={item.imgUrl || require('@/assets/module/component.png')}
                                                        />
                                                    </div>
                                                    <div className={styles.itemName}>
                                                        {item.nickname || item.name}
                                                    </div>
                                                </DragView>
                                            </Col>
                                        )
                                    })}
                                </Row>
                            </div>
                        )
                    })}
                </div>
            )
        },[store.list])

        return (
            <Tabs activeTab={activeTab} onChange={setActiveTab}
                className={styles.tabs}
            >
                <Tabs.TabPane title="图标">
                    <IconList />
                </Tabs.TabPane>
                <Tabs.TabPane title="基础" key="system">
                    {systems}
                </Tabs.TabPane>
                <Tabs.TabPane title="模块列表" key="custom">
                    {customs}
                </Tabs.TabPane>
            </Tabs>
        )
    })

}

export default ModuleList;